package com.example.editor.metamodel.export;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.stereotype.Component;
import com.example.editor.metamodel.core.MetaAttribute;
import com.example.editor.metamodel.core.MetaClass;
import com.example.editor.metamodel.core.MetaEnum;
import com.example.editor.metamodel.core.MetaPrimitiveType;
import com.example.editor.metamodel.core.MetaRelation;
import com.example.editor.metamodel.core.MetaTypeReferenceKind;

/** Portable SQL DDL projection from canonical MetaModel. Foreign keys are emitted after tables so cycles stay safe. */
@Component
public class SqlDdlMetamodelExporter implements MetamodelTextExporter {
    /** Descripción: Ejecuta la operación «format» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ @Override public MetamodelExportFormat format(){return MetamodelExportFormat.SQL_DDL;}
    /** Descripción: Ejecuta la operación «export» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: context: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public String export(NeutralMetamodelExportContext context){
        StringBuilder out=new StringBuilder("-- HYDRA SQL DDL projection\n-- Metamodel source: ").append(context.neutralMetamodel().id()).append("\n\n");
        for(MetaEnum value:context.neutralMetamodel().enums()) out.append(enumDdl(value)).append("\n");
        Map<String,MetaClass> classes=MetamodelExportSupport.indexClasses(context);
        for(MetaClass metaClass:context.neutralMetamodel().classes()) out.append(tableDdl(context,metaClass)).append("\n");
        List<String> foreignKeys=new ArrayList<>();
        for(MetaClass source:context.neutralMetamodel().classes()) for(MetaRelation relation:MetamodelExportSupport.structuralRelationsFrom(context,source.id())) {
            MetaClass target=classes.get(relation.targetTypeId()); if(target!=null) foreignKeys.add(foreignKeyDdl(source,target,relation));
        }
        if(!foreignKeys.isEmpty()) out.append("-- Foreign keys are deferred until every table exists; this also supports reference cycles.\n").append(String.join("\n",foreignKeys));
        return out.toString();
    }
    /** Descripción: Ejecuta la operación «enumDdl» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private String enumDdl(MetaEnum value){return "CREATE TYPE "+qQualified(value.annotations().getOrDefault("sql.qualifiedName",value.name()))+" AS ENUM ("+value.literals().stream().map(item->literal(item.name())).collect(Collectors.joining(", "))+");\n";}
    /** Descripción: Ejecuta la operación «tableDdl» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: context: dato de entrada necesario para la operación; metaClass: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String tableDdl(NeutralMetamodelExportContext context,MetaClass metaClass){
        String table=metaClass.annotations().getOrDefault("sql.table",metaClass.name()); List<String> lines=new ArrayList<>();
        for(MetaAttribute attribute:metaClass.attributes()) {
            String column=attribute.annotations().getOrDefault("sql.column",attribute.name()); StringBuilder line=new StringBuilder("  ").append(q(column)).append(' ').append(sqlType(context,attribute));
            if(attribute.multiplicity()!=null&&attribute.multiplicity().lowerBound()>0)line.append(" NOT NULL");
            if(!attribute.defaultValue().isBlank())line.append(" DEFAULT ").append(attribute.defaultValue());
            if("true".equalsIgnoreCase(attribute.annotations().get("sql.unique")))line.append(" UNIQUE");
            if("true".equalsIgnoreCase(attribute.annotations().get("sql.generated")))line.append(" GENERATED BY DEFAULT AS IDENTITY"); lines.add(line.toString());
        }
        List<String> primary=csv(metaClass.annotations().get("sql.primaryKeys"));
        if(primary.isEmpty()) primary=metaClass.attributes().stream().filter(a->"true".equalsIgnoreCase(a.annotations().get("sql.primaryKey"))).map(a->a.annotations().getOrDefault("sql.column",a.name())).toList();
        if(!primary.isEmpty())lines.add("  PRIMARY KEY ("+primary.stream().map(SqlDdlMetamodelExporter::q).collect(Collectors.joining(", "))+")");
        return "CREATE TABLE "+qQualified(table)+" (\n"+String.join(",\n",lines)+"\n);\n";
    }
    /** Descripción: Ejecuta la operación «foreignKeyDdl» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: source: dato de entrada necesario para la operación; target: dato de entrada necesario para la operación; relation: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String foreignKeyDdl(MetaClass source,MetaClass target,MetaRelation relation){
        String sourceTable=source.annotations().getOrDefault("sql.table",source.name()),targetTable=target.annotations().getOrDefault("sql.table",target.name());
        List<String> sourceColumns=csv(relation.annotations().get("sql.columns")),targetColumns=csv(relation.annotations().get("sql.targetColumns"));
        if(sourceColumns.isEmpty())sourceColumns=List.of(relation.name()+"_id"); if(targetColumns.isEmpty())targetColumns=List.of(primaryColumn(target));
        String constraint=relation.annotations().getOrDefault("sql.foreignKey","fk_"+safe(sourceTable)+"_"+safe(relation.name()));
        StringBuilder ddl=new StringBuilder("ALTER TABLE ").append(qQualified(sourceTable)).append(" ADD CONSTRAINT ").append(q(constraint)).append(" FOREIGN KEY (")
                .append(sourceColumns.stream().map(SqlDdlMetamodelExporter::q).collect(Collectors.joining(", "))).append(") REFERENCES ").append(qQualified(targetTable)).append(" (")
                .append(targetColumns.stream().map(SqlDdlMetamodelExporter::q).collect(Collectors.joining(", "))).append(')');
        String onDelete=relation.annotations().getOrDefault("sql.onDelete",""); if(!onDelete.isBlank())ddl.append(" ON DELETE ").append(onDelete);
        String onUpdate=relation.annotations().getOrDefault("sql.onUpdate",""); if(!onUpdate.isBlank())ddl.append(" ON UPDATE ").append(onUpdate); return ddl.append(";\n").toString();
    }
    /** Descripción: Ejecuta la operación «sqlType» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: context: dato de entrada necesario para la operación; attribute: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String sqlType(NeutralMetamodelExportContext context,MetaAttribute attribute){
        String preserved=attribute.annotations().get("sql.type");if(preserved!=null&&!preserved.isBlank())return preserved;if(attribute.type()==null)return "VARCHAR(255)";
        if(attribute.type().kind()==MetaTypeReferenceKind.ENUM){var value=MetamodelExportSupport.indexEnums(context).get(attribute.type().targetId());return value==null?"VARCHAR(255)":qQualified(value.annotations().getOrDefault("sql.qualifiedName",value.name()));}
        if(attribute.type().kind()!=MetaTypeReferenceKind.PRIMITIVE)return "VARCHAR(255)";
        try{return switch(MetaPrimitiveType.valueOf(attribute.type().targetId())){case STRING->"VARCHAR(255)";case BOOLEAN->"BOOLEAN";case BYTE,SHORT->"SMALLINT";case INTEGER->"INTEGER";case LONG,BIG_INTEGER->"BIGINT";case FLOAT->"REAL";case DOUBLE->"DOUBLE PRECISION";case DECIMAL->"DECIMAL(38,10)";case CHARACTER->"CHAR(1)";case DATE->"TIMESTAMP";case BINARY->"BLOB";case OBJECT->"TEXT";};}catch(IllegalArgumentException ignored){return "VARCHAR(255)";}
    }
    /** Descripción: Ejecuta la operación «primaryColumn» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: metaClass: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String primaryColumn(MetaClass metaClass){List<String> values=csv(metaClass.annotations().get("sql.primaryKeys"));if(!values.isEmpty())return values.get(0);for(MetaAttribute attribute:metaClass.attributes())if("true".equalsIgnoreCase(attribute.annotations().get("sql.primaryKey")))return attribute.annotations().getOrDefault("sql.column",attribute.name());for(MetaAttribute attribute:metaClass.attributes())if("id".equalsIgnoreCase(attribute.name()))return attribute.annotations().getOrDefault("sql.column",attribute.name());return metaClass.attributes().isEmpty()?"id":metaClass.attributes().get(0).annotations().getOrDefault("sql.column",metaClass.attributes().get(0).name());}
    /** Descripción: Ejecuta la operación «csv» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static List<String> csv(String value){if(value==null||value.isBlank())return List.of();return java.util.Arrays.stream(value.split(",")).map(String::trim).filter(item->!item.isBlank()).toList();}
    /** Descripción: Ejecuta la operación «q» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String q(String value){return "\""+(value==null?"":value.replace("\"","\"\""))+"\"";}
    /** Descripción: Ejecuta la operación «qQualified» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String qQualified(String value){return java.util.Arrays.stream((value==null?"":value).split("\\.")).map(SqlDdlMetamodelExporter::q).collect(Collectors.joining("."));}
    /** Descripción: Ejecuta la operación «literal» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String literal(String value){return "'"+(value==null?"":value.replace("'","''"))+"'";}
    /** Descripción: Ejecuta la operación «safe» correspondiente a la responsabilidad de SqlDdlMetamodelExporter. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String safe(String value){return (value==null?"":value).replaceAll("[^A-Za-z0-9_]+","_");}
}
